function encodePcm16Wav(audio:AudioBuffer){const channels=audio.numberOfChannels,samples=audio.length,blockAlign=channels*2,buffer=new ArrayBuffer(44+samples*blockAlign),view=new DataView(buffer);writeAscii(view,0,'RIFF');view.setUint32(4,36+samples*blockAlign,true);writeAscii(view,8,'WAVE');writeAscii(view,12,'fmt ');view.setUint32(16,16,true);view.setUint16(20,1,true);view.setUint16(22,channels,true);view.setUint32(24,audio.sampleRate,true);view.setUint32(28,audio.sampleRate*blockAlign,true);view.setUint16(32,blockAlign,true);view.setUint16(34,16,true);writeAscii(view,36,'data');view.setUint32(40,samples*blockAlign,true);const data=Array.from({length:channels},(_,ch)=>audio.getChannelData(ch));let offset=44;for(let i=0;i<samples;i++)for(let ch=0;ch<channels;ch++){const x=Math.max(-1,Math.min(1,data[ch][i]));view.setInt16(offset,x<0?x*32768:x*32767,true);offset+=2}return new Blob([buffer],{type:'audio/wav'})}
function writeAscii(view:DataView,offset:number,value:string){for(let i=0;i<value.length;i++)view.setUint8(offset+i,value.charCodeAt(i))}
function downloadUrl(url:string,name:string){const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}

