function Spectrogram({result}:{result:RecordingAnalysis['spectrogram']}){const canvas=useRef<HTMLCanvasElement>(null);useEffect(()=>{const c=canvas.current;if(!c)return;const ctx=c.getContext('2d');if(!ctx)return;const rows=result.magnitude_db_re_1_sample_amplitude;const height=220,width=700;c.width=width;c.height=height;const flat=rows.flat(),low=Math.max(-120,Math.min(...flat)),high=Math.max(-10,Math.max(...flat)),image=ctx.createImageData(width,height);for(let x=0;x<width;x++){const col=Math.min(result.times_s.length-1,Math.floor(x*result.times_s.length/width));for(let y=0;y<height;y++){const row=Math.min(rows.length-1,Math.floor((height-1-y)*rows.length/height));const v=(rows[row]?.[col]??low);const t=Math.max(0,Math.min(1,(v-low)/(high-low||1)));const i=(y*width+x)*4;image.data[i]=Math.round(20+40*t);image.data[i+1]=Math.round(38+195*t);image.data[i+2]=Math.round(54+195*t);image.data[i+3]=255}}ctx.putImageData(image,0,0)},[result]);return <div className="spectrogram-wrap"><canvas ref={canvas}/><div className="spec-frequency-labels"><span>{result.frequencies_hz[0]?.toFixed(0)} Hz</span><span>{result.frequencies_hz[Math.floor(result.frequencies_hz.length/2)]?.toFixed(0)} Hz</span><span>{result.frequencies_hz[result.frequencies_hz.length-1]?.toFixed(0)} Hz</span></div><div className="spec-axes"><span>0 s</span><span>{result.times_s[result.times_s.length-1]?.toFixed(3)} s</span><span>Frequency axis shown at left · magnitude in dB</span><span>low <i/> high</span></div></div>}

